  # Brand colours for link tiles (official palettes; near-black brands stay ink).
  BRANDS = {
    "github.com" => "#24292F", "x.com" => "#0F1419", "twitter.com" => "#0F1419",
    "linkedin.com" => "#0A66C2", "youtube.com" => "#FF0000", "youtu.be" => "#FF0000",
    "instagram.com" => "#E1306C", "bsky.app" => "#0085FF", "mastodon.social" => "#6364FF",
    "threads.net" => "#101010", "dribbble.com" => "#EA4C89", "medium.com" => "#12100E",
    "substack.com" => "#FF6719", "dev.to" => "#0A0A0A", "tiktok.com" => "#010101",
    "twitch.tv" => "#9146FF", "discord.gg" => "#5865F2", "discord.com" => "#5865F2",
    "t.me" => "#26A5E4", "gitlab.com" => "#FC6D26", "behance.net" => "#1769FF", "figma.com" => "#F24E1E"
  }.freeze
  FALLBACK_BRAND = "#3A3AF4"

  def link_brand(url)
    host = link_host(url)
    key  = BRANDS.keys.find { |h| host == h || host.end_with?(".#{h}") }
    key ? BRANDS[key] : FALLBACK_BRAND
  end

  # Generic fallback: an outward arrow, drawn to match the 24px grid.
  FALLBACK = "M7 17 17 7M8 7h9v9".freeze

  def link_icon(url, size: 24)
    host = URI.parse(url.to_s).host.to_s.downcase.delete_prefix("www.")
    key  = ICONS.keys.find { |h| host == h || host.end_with?(".#{h}") }
    if key
      tag.svg(tag.path(d: ICONS[key]), viewBox: "0 0 24 24", width: size, height: size,
              fill: "currentColor", "aria-hidden": true, class: "link-glyph")
    else
      tag.svg(tag.path(d: FALLBACK), viewBox: "0 0 24 24", width: size, height: size,
              fill: "none", stroke: "currentColor", "stroke-width": 2, "stroke-linecap": "round",
              "stroke-linejoin": "round", "aria-hidden": true, class: "link-glyph link-glyph--generic")
    end
  rescue URI::InvalidURIError
    tag.svg(tag.path(d: FALLBACK), viewBox: "0 0 24 24", width: size, height: size, fill: "none",
            stroke: "currentColor", "stroke-width": 2, "stroke-linecap": "round", "aria-hidden": true, class: "link-glyph link-glyph--generic")
  end

  def link_host(url)
    URI.parse(url.to_s).host.to_s.downcase.delete_prefix("www.")
  rescue URI::InvalidURIError
    url.to_s.sub(%r{\Ahttps?://}i, "").split("/").first.to_s
  end
end
